import {lifestyleChoices,lifestyleSnapshot,lifestyleInputs,visibleBudgetGroups,nextLifestyleQuestion} from './lifestyle-state.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const link=(text,route,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="#/${route}">${text}</a>`;
const sourceNote=`<p class="subtle">A future-life illustration for one adult in Austin, using Approach 1’s editable spending assumptions and 2026 tax model. These are planning amounts, not current price quotes or college living costs.</p>`;
export function lifestyleLens(draft,{compact=false}={}){const goal=lifestyleSnapshot(draft);if(goal.status!=='ready'||!goal.confirmed)return`<aside class="callout lifestyle-lens"><div><h3>${goal.status==='unanswered'?'What kind of life are you picturing?':'Review your lifestyle picture'}</h3><p>${goal.status==='unanswered'?'Keep your future lifestyle alongside your college interests. All pathways stay open.':'Your latest choices are saved. Review the amounts before using the updated goal.'}</p></div>${link(goal.status==='unanswered'?'Picture my lifestyle':'Review my lifestyle',goal.status==='unanswered'?'lifestyle':'lifestyle/summary',true)}</aside>`;return`<aside class="profile-strip lifestyle-lens"><div><span class="eyebrow" style="margin-bottom:8px">My future lifestyle · Austin illustration</span><strong>${money(goal.range.low)} to cover the budget · ${money(goal.range.high)} with breathing room</strong><p>Annual income before tax. ${compact?'':'A 20% take-home buffer shapes the upper target. '}This goal stays separate from your interest suggestions.</p></div><a class="text-link" href="#/lifestyle/summary">Review my lifestyle ↗</a></aside>`;}
export function lifestylePage(draft,index=null){if(index!==null)return questionPage(draft,index);const answered=Object.keys(draft.builder.choices).length,goal=lifestyleSnapshot(draft);return`<div class="wrap"><section class="page-intro"><span class="eyebrow">My lifestyle expectations</span><h1>A life to picture.<br>A direction to explore.</h1><p class="lede">Where would you like to live? What would you make room for? Start with the life you’re curious about, then keep that picture beside your college pathways.</p></section><div class="detail-grid"><div><section class="panel"><h2>Nine everyday choices.</h2><p>Home, getting around, food, dinners out, travel, entertainment, hobbies, clothing and saving. Pick what appeals to you, then adjust the amounts to make the picture your own.</p><div class="actions">${link(answered?'Continue my lifestyle ('+answered+'/9)':'Start my lifestyle picture','lifestyle/'+nextLifestyleQuestion(draft))}${goal.status!=='unanswered'?link('Review my budget','lifestyle/summary',true):''}</div><a class="text-link" href="#/pathways">Explore college pathways without a budget ↗</a></section><section class="panel"><h3>Keep both questions in view</h3><p><strong>What would I enjoy studying?</strong> Your interest reflection helps you explore subjects and learning routes.</p><p><strong>What life would I like to support?</strong> Your lifestyle picture gives you a financial goal to investigate as you compare future possibilities.</p><p>All college pathways remain available, whatever budget you choose.</p></section></div><aside><section class="panel"><span class="eyebrow">Your future, in everyday terms</span><div class="lifestyle-icons" aria-hidden="true">⌂　↗　☕　✈　✳</div>${sourceNote}<p class="subtle">This questionnaire and its underlying budget calculation are reused from Approach 1. Your answers save separately in Approach 2 on this browser.</p></section></aside></div></div>`;}
function questionPage(draft,index){const q=lifestyleChoices[index];if(!q)return lifestylePage(draft);const selected=draft.builder.choices[q.id],options=q.id==='home'&&draft.builder.homeMode==='own'?q.ownOptions:q.options,answered=Object.keys(draft.builder.choices).length;return`<div class="wrap"><div class="question-layout lifestyle-question"><a class="back" href="#/lifestyle">← My lifestyle picture</a><span class="eyebrow">Lifestyle expectation · ${index+1} of 9</span><div class="progress-track" role="progressbar" aria-label="Lifestyle questions answered" aria-valuenow="${answered}" aria-valuemin="0" aria-valuemax="9"><div style="width:${answered/9*100}%"></div></div><h1>${h(q.question)}</h1>${q.id==='home'?`<fieldset class="home-modes"><legend>Picture a housing route</legend>${[['rent','Renting'],['own','Owning']].map(([mode,label])=>`<label><input type="radio" name="housing-mode" data-home-mode="${mode}" ${draft.builder.homeMode===mode?'checked':''}>${label}</label>`).join('')}</fieldset>`:''}<fieldset class="lifestyle-options"><legend class="subtle">Choose one possibility. You can change it later.</legend>${options.map((o,i)=>`<label class="lifestyle-option ${selected===i?'selected':''}"><input type="radio" name="lifestyle-choice" value="${i}" data-lifestyle-question="${q.id}" ${selected===i?'checked':''}><span><strong>${h(o.title)}</strong><small>${h(o.copy)}</small></span><span class="option-tick" aria-hidden="true">${selected===i?'✓':''}</span></label>`).join('')}</fieldset><div class="question-foot">${index?`<a href="#/lifestyle/${index-1}">← Previous</a>`:'<a href="#/lifestyle">← Introduction</a>'}<button class="button small" data-lifestyle-next="${index}">${index===8?'Review my lifestyle':'Continue →'}</button></div><p id="lifestyle-error" class="form-error" role="alert"></p><a class="text-link" href="#/pathways">Pause & explore college pathways</a>${sourceNote}</div></div>`;}
export function budgetPreview(draft){const goal=lifestyleSnapshot(draft);if(goal.status==='unanswered')return`<section class="panel"><h2>Finish shaping your picture.</h2><p>${goal.answered} of 9 choices saved. Unanswered choices have no budget assigned yet.</p>${link('Continue my lifestyle','lifestyle/'+nextLifestyleQuestion(draft))}</section>`;if(goal.status==='invalid')return`<section class="panel"><h2>A few amounts need a look.</h2><p role="alert">Review: ${goal.issues.map(h).join(', ')}. Amounts must be non-negative, with a valid loan term and percentage.</p><p>No income goal is shown until these inputs are valid.</p></section>`;return`<section class="panel goal-panel"><span class="eyebrow">An income goal to investigate</span><h2>${money(goal.range.low)}<span class="goal-unit"> / year before tax</span></h2><p>Estimated minimum annual income to cover the spending and savings in this picture.</p><div class="breathing-room"><strong>${money(goal.range.high)} / year</strong><span>adds breathing room: 20% of take-home pay after the health budget.</span></div><p class="subtle">Includes estimated federal and payroll taxes, health costs and your retirement setting. Single-filer employee illustration, 40 hours per week and 52 paid weeks, in Texas; actual circumstances vary.</p>${goal.retirementCapped?'<p class="note">At this income, the retirement calculation is capped at the model’s 2026 employee contribution limit of $24,500. It does not maintain the full percentage above that cap.</p>':''}${goal.inputs.housingMode==='own'?`<p class="note">Owning also needs upfront cash. This model estimates ${money(goal.result.upfront)} for the down payment, 3% closing costs and a six-month essential-cost reserve; the gap after the cash you entered is ${money(goal.result.upfrontGap)}. Monthly affordability alone does not cover this.</p>`:''}${goal.result.carUpfront>0?`<p class="subtle">Car down payment: ${money(goal.result.carUpfront)} upfront, in addition to monthly costs.</p>`:''}<p class="subtle">The goal is not a salary prediction, an upper income limit or a statistical confidence interval.</p></section><section class="panel"><h3>Your monthly picture</h3><div class="budget-rows">${goal.rows.filter(r=>r.value>0).map(r=>`<div><span>${h(r.label)}</span><strong>${money(r.value)}</strong></div>`).join('')}<div class="budget-total"><span>Spending, cash saving & health</span><strong>${money(goal.total)} / month</strong></div></div><p class="subtle">Retirement contributions and taxes are handled separately when translating the budget into gross income. Monthly health is included once. Display amounts are rounded.</p></section>`;}
function editor(draft){const inputs=lifestyleInputs(draft);if(!inputs)return'';return`<details class="panel budget-editor"><summary>Adjust the amounts and assumptions</summary><p>Keep the same lifestyle choices and edit their planning amounts. Any change needs a fresh confirmation before the goal appears elsewhere.</p>${visibleBudgetGroups(inputs).map(g=>`<fieldset><legend>${h(g.title)}</legend><div class="budget-fields">${g.fields.map(([key,label])=>`<label for="budget-${key}"><span>${h(label)}</span><input id="budget-${key}" type="number" inputmode="decimal" min="0" step="any" data-budget-field="${key}" value="${h(inputs[key])}"></label>`).join('')}</div></fieldset>`).join('')}<p class="subtle">Dollar amounts are USD. Rates are percentages; meal frequency and loan terms use the units shown.</p></details>`;}
export function lifestyleSummaryPage(draft){const goal=lifestyleSnapshot(draft);return`<div class="wrap"><a class="back" href="#/lifestyle">← My lifestyle picture</a><section class="page-intro"><span class="eyebrow">A financial goal alongside your college plan</span><h1>What could this<br>picture take?</h1><p class="lede">Review the costs, adjust what matters to you, and keep the result beside the subjects you want to explore.</p></section><div class="detail-grid"><div><div id="budget-preview" aria-live="polite">${budgetPreview(draft)}</div>${editor(draft)}</div><aside><section class="panel"><h3>The choices behind this picture</h3><div class="choice-summary">${lifestyleChoices.map((q,i)=>{const options=q.id==='home'&&draft.builder.homeMode==='own'?q.ownOptions:q.options,choice=options[draft.builder.choices[q.id]];return`<div><span>${h(q.id==='home'?'Home · '+draft.builder.homeMode:q.id.charAt(0).toUpperCase()+q.id.slice(1))}</span><a href="#/lifestyle/${i}">${choice?h(choice.title):'Not answered'} ↗</a></div>`;}).join('')}</div></section><section class="panel"><h3>Keep the pathway open</h3><p>Your lifestyle is a comparison lens. It does not change your interest scores, rank majors by salary or remove college pathways.</p><p>A major can lead toward different careers, with different pay and preparation. Compare selected local earning examples across your college pathways, with further study and experienced destinations shown separately. You do not need to choose a profession.</p></section></aside></div>${goal.status!=='unanswered'?`<div class="actions"><button class="button" data-confirm-lifestyle>${goal.confirmed?'Keep my lifestyle goal':'Use this lifestyle goal'} ↗</button>${link('Continue to interest questions','interests',true)}${link('Explore college pathways','pathways',true)}</div><p id="lifestyle-error" class="form-error" role="alert"></p><p id="lifestyle-save-status" class="subtle">${goal.confirmed?'Your confirmed goal is saved in this browser for Approach 2.':'Your draft is saved. Confirm it to use the goal alongside your pathways.'}</p>`:''}<details class="panel"><summary>Sources, scope & privacy</summary>${sourceNote}<p>Tax and retirement assumptions are preserved from Approach 1’s 2026 illustration. Household circumstances, benefits, later tax years and prices can differ. The income goal solves for the budget you entered; it does not estimate what a particular major will earn.</p><ul><li><a href="https://www.irs.gov/newsroom/working-families-tax-cuts-individuals-and-workers" target="_blank" rel="noopener">IRS individual tax information</a></li><li><a href="https://www.ssa.gov/pubs/EN-05-10003.pdf" target="_blank" rel="noopener">Social Security employee payroll tax information</a></li><li><a href="https://www.huduser.gov/portal/datasets/fmr.html" target="_blank" rel="noopener">HUD rent benchmark context</a></li></ul><p>Answers save only in this prototype’s browser storage. They are not transferred to Approach 1 or included in the shared interest-answer format. Exporting a full draft includes your lifestyle choices and budget.</p></details></div>`;}
